const LEDGER_DECODE_CHUNK_SIZE = 65536;

async function visitLedger(stream, visitor) {
  const reader = stream.getReader();
  const decoder = new TextDecoder("utf-8");
  let fragments = [];
  let line = 1;
  let accepted = 0;
  let rejected = 0;
  let reachedEOF = false;
  let cancelled = false;

  async function visitLine(text) {
    if (text.trim().length === 0) {
      return false;
    }

    let value;
    try {
      value = JSON.parse(text);
    } catch {
      rejected += 1;
      return false;
    }

    accepted += 1;
    return (await visitor({ line, value })) === false;
  }

  async function consume(text) {
    let start = 0;

    while (true) {
      const end = text.indexOf("\n", start);
      if (end === -1) {
        if (start < text.length) {
          fragments.push(text.slice(start));
        }
        return false;
      }

      let current;
      if (fragments.length === 0) {
        current = text.slice(start, end);
      } else {
        fragments.push(text.slice(start, end));
        current = fragments.join("");
        fragments = [];
      }

      if (await visitLine(current)) {
        return true;
      }

      line += 1;
      start = end + 1;
    }
  }

  try {
    while (true) {
      const result = await reader.read();

      if (result.done) {
        reachedEOF = true;

        const tail = decoder.decode();
        if (tail.length !== 0 && await consume(tail)) {
          return { accepted, rejected, stopped: true };
        }

        if (fragments.length !== 0) {
          const current = fragments.join("");
          fragments = [];

          if (await visitLine(current)) {
            return { accepted, rejected, stopped: true };
          }
        }

        return { accepted, rejected, stopped: false };
      }

      const bytes = result.value;

      for (let offset = 0; offset < bytes.length; offset += LEDGER_DECODE_CHUNK_SIZE) {
        const decoded = decoder.decode(
          bytes.subarray(offset, offset + LEDGER_DECODE_CHUNK_SIZE),
          { stream: true }
        );

        if (decoded.length !== 0 && await consume(decoded)) {
          await reader.cancel();
          cancelled = true;
          return { accepted, rejected, stopped: true };
        }
      }
    }
  } catch (error) {
    if (!cancelled) {
      await reader.cancel();
      cancelled = true;
    }
    throw error;
  } finally {
    reader.releaseLock();
  }
}
